  std::cout << std::endl;
  std::cout << "Arguments:" << std::endl;
  std::cout << "  --path         Path to the collection (required)"
            << std::endl;
}


int main(int argc, char **argv) {
  Config config;

  // Parse arguments
  if (!ParseArgs(argc, argv, config)) {
    PrintUsage(argv[0]);
#ifdef __ANDROID__
    _exit(1);
#endif
    return 1;
  }

  try {
    std::filesystem::path cwd = std::filesystem::current_path();
